mapper.select:
select
a.menu_id,
a.menu_name,
a.menu_code,
a.up_id,
a.icon_code,
a.icon_url,
a.menu_type,
a.menu_level,
a.element_code,
a.state,
a.sort,
a.link_type,
a.url,
a.creator_id,
a.sys_state
from sys_menu a
where 1 = 1
 and a.menu_id = #{menuId, jdbcType=BIGINT}
 and a.menu_name = #{menuName, jdbcType=VARCHAR}
 and a.menu_code = #{menuCode, jdbcType=VARCHAR}
 and a.up_id = #{upId, jdbcType=BIGINT}
 and a.icon_code = #{iconCode, jdbcType=VARCHAR}
 and a.icon_url = #{iconUrl, jdbcType=VARCHAR}
 and a.menu_type = #{menuType, jdbcType=INTEGER}
 and a.menu_level = #{menuLevel, jdbcType=INTEGER}
 and a.element_code = #{elementCode, jdbcType=VARCHAR}
 and a.state = #{state, jdbcType=INTEGER}
 and a.sort = #{sort, jdbcType=INTEGER}
 and a.link_type = #{linkType, jdbcType=INTEGER}
 and a.url = #{url, jdbcType=VARCHAR}
 and a.creator_id = #{creatorId, jdbcType=BIGINT}
 and a.sys_state = #{sysState, jdbcType=INTEGER}

